    print("no .env.local")
else:
    env = {}
    for line in p.read_text(encoding="utf-8").splitlines():
        m = re.match(r'^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*"?(.*?)"?\s*$', line)
