import re, socket
from pathlib import Path
p = Path(".env.local")
raw = p.read_text(encoding="utf-8")
env = {}
for line in raw.splitlines():
    m = re.match(r'^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*"?(.*?)"?\s*$', line)
    if m:
        env[m.group(1)] = m.group(2)

print("flag check (no values shown):")
for k in ("DATABASE_URL", "POSTGRES_PRISMA_URL", "DATABASE_URL_UNPOOLED"):
    v = env.get(k, "")
    if v:
        print(f"  {k}: pgbouncer={'pgbouncer=true' in v} pooled={'-pooler' in v} sslmode={'sslmode=' in v}")

unpooled = env.get("DATABASE_URL_UNPOOLED") or env.get("POSTGRES_URL_NON_POOLING")
if "DIRECT_URL" not in env and unpooled:
    if not raw.endswith("\n"):
        raw += "\n"
    raw += f'\n# Prisma migrations run on the unpooled connection\nDIRECT_URL="{unpooled}"\n'
    p.write_text(raw, encoding="utf-8")
    print("\nadded DIRECT_URL (copied from DATABASE_URL_UNPOOLED)")

print("\nreachability:")
for k in ("DATABASE_URL", "DIRECT_URL"):
    v = env.get(k) or unpooled
    host = re.search(r'@([^/:?]+)', v).group(1)
    try:
        socket.create_connection((host, 5432), timeout=8).close()
        print(f"  {k}: host reachable on 5432 (...{host[-28:]})")
    except Exception as e:
        print(f"  {k}: UNREACHABLE - {type(e).__name__}: {e}")
PY
